import React from 'react';
import { Avatar, Box, Divider, IconButton, Stack, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { Bell, CaretLeft, Image, Info, Key, Keyboard, Lock, Note, PencilCircle } from 'phosphor-react';
import Shortcuts from '../../sections/main/Settings/Shortcuts';
import ThemeDialog from '../../sections/main/Settings/ThemeDialog';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';



const Settings = () => {

  const theme = useTheme();
  const { user } = useSelector((state) => state.app);
  const [openShortcuts, setOpenShortcuts] = React.useState(false);
  const navigate = useNavigate();
  const handleOpenShortcuts = () => { setOpenShortcuts(true); }

  const [openTheme, setOpenTheme] = React.useState(false);

  const handleOpenTheme = () => {
    setOpenTheme(true);
  };
  const handleCloseTheme = () => {
    setOpenTheme(false);
  };

  const name = `${user?.firstName} ${user?.lastName}`;
  const handleCloseShortcuts = () => {
    setOpenShortcuts(false);
  }

  const list = [
    {
      key: 0,
      icon: <Bell size={20} />,
      title: 'Notifications',
      onclick: () => { },
    },
    {
      key: 1,
      icon: <Lock size={20} />,
      title: 'Privacy',
      onclick: () => { },
    },
    {
      key: 2,
      icon: <Key size={20} />,
      title: 'Security',
      onclick: () => { },
    },
    {
      key: 3,
      icon: <PencilCircle size={20} />,
      title: 'Theme',
      onclick: handleOpenTheme,
    },
    {
      key: 4,
      icon: <Image size={20} />,
      title: 'Chat Wallpaper',
      onclick: () => { },
    },
    {
      key: 5,
      icon: <Note size={20} />,
      title: 'Request Account Info',
      onclick: () => { },
    },
    {
      key: 6,
      icon: <Keyboard size={20} />,
      title: 'Keyboard Shortcuts',
      onclick: handleOpenShortcuts,
    },
    {
      key: 7,
      icon: <Info size={20} />,
      title: 'Help',
      onclick: () => { },
    },
  ];



  return (
    <>
      <Stack direction={'row'} sx={{ width: "100%" }}>
        {/* Left Panel */}
        <Box sx={{
          height: "100vh",
          width: 320,
          backgroundColor: theme.palette.mode === 'light' ? "#F8FAFF" : theme.palette.background,
          boxShadow: "0px 0px 2px rgba(0,0,0,0.25)"
        }}
        >
          <Stack p={4} spacing={2}>
            {/* Header */}
            <Stack direction={'row'} alignItems={'center'} spacing={3}>
              <IconButton onClick={() => {
                navigate("/app");
              }}>
                <CaretLeft />
              </IconButton>
              <Typography variant='h6'>Settings</Typography>
            </Stack>
            {/* Profile */}
            <Stack direction={'column'} spacing={2} pb={2} alignItems={'center'} justifyContent={'center'}>
              <a href={user?.avatar} target="_blank" rel="noopener noreferrer">
                <Avatar sx={{ width: 120, height: 120 }} src={user?.avatar} alt={user?.firstName} />
              </a>
              <Stack spacing={0.5}>
                <Typography variant='article'>{user?.firstName}</Typography>
                {/* <Typography variant='body2'>{user?.about}</Typography> */}
              </Stack>
            </Stack>
            {/* List of Options */}
            <Stack spacing={3}>
              {list.map(({ key, icon, title, onclick }) => <>
                <Stack spacing={2} sx={{ cursor: 'pointer' }} onClick={onclick}>
                  <Stack direction={'row'} spacing={2} alignItems={'center'}>
                    {icon}
                    <Typography variant='body2'>{title}</Typography>
                  </Stack>
                  {key !== 7 && <Divider />}
                </Stack>
              </>
              )}
            </Stack>
          </Stack>
        </Box>
      </Stack>
      {/* Right Panel */}
      {openTheme && <ThemeDialog open={openTheme} handleClose={handleCloseTheme} />}
      {openShortcuts && <Shortcuts open={openShortcuts} handleClose={handleCloseShortcuts} />}
    </>
  )
}

export default Settings;